(function () {
    function init() {
        const container =
            document.getElementById('scroll-gallery') ||
            document.getElementById('infinite-scroll-gallery');

        if (!container || Util.isMobile()) {
            if (!container) {
                console.warn('justified-gallery: #scroll-gallery or #infinite-scroll-gallery not found.');
            }
            return;
        }

        const config = {
            targetRowHeight:
                parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-target-row-height')) || 225,
            gap: parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--jg-gap')) || 4,
            justifyLastRow: false,
            resizeDebounce: 120,
            mutationDebounce: 120
        };

        function debounce(fn, wait) {
            let t;
            return function (...args) {
                clearTimeout(t);
                t = setTimeout(() => fn.apply(this, args), wait);
            };
        }

        function itemAspectRatio(itemEl) {
            const img = itemEl.querySelector('img');
            if (!img) return 1;
            if (img.dataset && img.dataset.aspect) return Number(img.dataset.aspect) || 1;
            if (img.hasAttribute('width') && img.hasAttribute('height')) {
                const w = Number(img.getAttribute('width'));
                const h = Number(img.getAttribute('height'));
                if (w > 0 && h > 0) return w / h;
            }
            if (img.naturalWidth && img.naturalHeight) return img.naturalWidth / img.naturalHeight;
            return 1;
        }

        function availableContentWidth(el) {
            // Use precise floating point measurement from getBoundingClientRect()
            // and subtract computed paddings so JS uses the exact same fractional width
            // used by the browser for wrapping/layout.
            const rect = el.getBoundingClientRect();
            const computed = getComputedStyle(el);
            const padLeft = parseFloat(computed.paddingLeft) || 0;
            const padRight = parseFloat(computed.paddingRight) || 0;
            return Math.max(1, rect.width - padLeft - padRight);
        }

        // Wait for images in a section to decode/load to avoid layout jitter
        async function waitForSectionImages(sectionEl) {
            const imgs = Array.from(sectionEl.querySelectorAll('img'));
            if (!imgs.length) return;
            await Promise.all(imgs.map(img => {
                if (img.decode) return img.decode().catch(() => Promise.resolve());
                if (img.complete && img.naturalWidth) return Promise.resolve();
                return new Promise(res => { img.onload = img.onerror = res; });
            }));
        }

        function layoutDateBody(dateBodyEl) {
            if (!dateBodyEl) return;
            const gap = config.gap;
            const containerWidth = availableContentWidth(dateBodyEl);
            // Only treat .photo-thumbnail-container as items, ignore stray spans etc.
            const itemEls = Array.from(dateBodyEl.querySelectorAll('.photo-thumbnail-container'));
            if (itemEls.length === 0) return;

            // clear sizing and ensure consistent flex/block behavior
            itemEls.forEach(el => {
                el.style.width = '';
                el.style.height = '';
                el.style.marginRight = '';
                el.style.marginBottom = '';
                el.style.boxSizing = 'border-box';
                el.style.flex = '0 0 auto';
                el.style.display = 'block';
            });

            const items = itemEls.map(el => ({ el, aspect: itemAspectRatio(el) || 1 }));

            const rows = [];
            let row = [];
            let rowAspectSum = 0;
            const targetH = config.targetRowHeight;

            items.forEach((it, idx) => {
                row.push(it);
                rowAspectSum += it.aspect;
                const rowWAtTarget = rowAspectSum * targetH + (row.length - 1) * gap;

                if (rowWAtTarget >= containerWidth) {
                    rows.push({ items: row.slice(), aspectSum: rowAspectSum, isLast: false });
                    row = [];
                    rowAspectSum = 0;
                } else {
                    if (idx === items.length - 1) {
                        rows.push({ items: row.slice(), aspectSum: rowAspectSum, isLast: true });
                        row = [];
                        rowAspectSum = 0;
                    }
                }
            });

            rows.forEach(r => {
                const isLast = r.isLast;
                if (isLast && !config.justifyLastRow) {
                    // Keep a stable target height for last row (non-justified)
                    const height = targetH;
                    r.items.forEach((it, i) => {
                        const w = it.aspect * height;
                        it.el.style.width = w.toFixed(3) + 'px';
                        it.el.style.height = height.toFixed(3) + 'px';
                        it.el.style.marginRight = (i < r.items.length - 1) ? gap + 'px' : '0px';
                        it.el.style.marginBottom = gap + 'px';
                    });
                } else {
                    // Justify this logical row exactly to the available width
                    const totalGap = (r.items.length - 1) * gap;
                    const height = (containerWidth - totalGap) / r.aspectSum;
                    let usedWidth = 0;
                    r.items.forEach((it, i) => {
                        const w = it.aspect * height;
                        usedWidth += w;
                        it.el.style.width = w.toFixed(3) + 'px';
                        it.el.style.height = height.toFixed(3) + 'px';
                        it.el.style.marginRight = (i < r.items.length - 1) ? gap + 'px' : '0px';
                        it.el.style.marginBottom = gap + 'px';
                    });

                    // Floating point rounding may leave a tiny discrepancy; fix the last item
                    const discrepancy = (containerWidth - totalGap) - usedWidth;
                    if (Math.abs(discrepancy) >= 0.001 && r.items.length) {
                        const lastEl = r.items[r.items.length - 1].el;
                        const current = parseFloat(lastEl.style.width) || 0;
                        lastEl.style.width = (current + discrepancy).toFixed(3) + 'px';
                    }
                }
            });
        }

        function layoutAllSections() {
            const dateBodies = container.querySelectorAll('.row.image-group-padding');
            dateBodies.forEach(db => layoutDateBody(db));
        }
        const debouncedLayoutAll = debounce(layoutAllSections, config.resizeDebounce);

        function layoutDateSection(sectionEl) {
            if (!sectionEl) return;
            const row = sectionEl.parentElement && sectionEl.parentElement.querySelector('.row.image-group-padding');
            if (row) layoutDateBody(row);
            else {
                const r2 = sectionEl.querySelector('.row.image-group-padding');
                if (r2) layoutDateBody(r2);
            }
        }

        async function waitAndLayoutRow(rowEl) {
            try {
                await waitForSectionImages(rowEl);
            } catch (e) {
                // ignore image decode errors
            } finally {
                layoutDateBody(rowEl);
            }
        }

        let contentAppendedCallback = null;
        function setContentAppendedCallback(cb) {
            contentAppendedCallback = typeof cb === 'function' ? cb : null;
        }

        const onMutations = debounce(function (mutations) {
            const addedRows = new Set();
            let newContentDetected = false;

            for (const m of mutations) {
                if (m.type === 'childList') {
                    m.addedNodes.forEach(node => {
                        if (!(node instanceof Element)) return;
                        if (node.classList && node.classList.contains('dateContainer')) {
                            const row = node.querySelector('.row.image-group-padding');
                            if (row) { addedRows.add(row); newContentDetected = true; }
                        } else {
                            if (node.matches && node.matches('.row.image-group-padding')) {
                                addedRows.add(node);
                                newContentDetected = true;
                            } else {
                                node.querySelectorAll && node.querySelectorAll('.row.image-group-padding').forEach(r => { addedRows.add(r); newContentDetected = true; });
                            }
                        }
                    });

                    m.addedNodes.forEach(node => {
                        if (!(node instanceof Element)) return;
                        if (node.matches && node.matches('.photo-thumbnail-container')) {
                            const rowParent = node.closest('.row.image-group-padding');
                            if (rowParent) { addedRows.add(rowParent); newContentDetected = true; }
                        } else {
                            node.querySelectorAll && node.querySelectorAll('.photo-thumbnail-container').forEach(n => {
                                const rowParent = n.closest('.row.image-group-padding');
                                if (rowParent) { addedRows.add(rowParent); newContentDetected = true; }
                            });
                        }
                    });
                }
            }

            if (addedRows.size > 0) {
                addedRows.forEach(rowEl => waitAndLayoutRow(rowEl));
            } else {
                layoutAllSections();
            }

            if (newContentDetected && contentAppendedCallback) {
                try { contentAppendedCallback(); } catch (e) { console.error('contentAppendedCallback error', e); }
            }
        }, config.mutationDebounce);

        const mo = new MutationObserver(onMutations);
        mo.observe(container, { childList: true, subtree: true });

        function disconnectObserver() { mo.disconnect(); }
        function reconnectObserver() { mo.observe(container, { childList: true, subtree: true }); }

        // Public API (minimal, no UI state changes)
        window.ScrollJustifiedGalleryInfinite = {
            layoutAll: layoutAllSections,
            layoutSection: layoutDateSection,
            waitForSectionImages: waitForSectionImages,
            setContentAppendedCallback: setContentAppendedCallback,
            disconnectObserver: disconnectObserver,
            reconnectObserver: reconnectObserver
        };

        // Initial layout: wait for rows' images to decode to reduce flashes
        setTimeout(() => {
            const rows = Array.from(container.querySelectorAll('.row.image-group-padding'));
            if (rows.length === 0) { layoutAllSections(); return; }
            Promise.all(rows.map(row => waitForSectionImages(row))).then(() => {
                layoutAllSections();
            }).catch(() => {
                layoutAllSections();
            });
        }, 20);

        // recompute on resize
        window.addEventListener('resize', debouncedLayoutAll);
        const resizeObserver = new ResizeObserver(debouncedLayoutAll);
        resizeObserver.observe(container);
    } // end init

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    }
})();